import json, sys, requests

URL = "http://127.0.0.1:8108/mcp"
HDR = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}

def parse(resp):
    ct = resp.headers.get("content-type","")
    if "text/event-stream" in ct:
        out = []
        for line in resp.text.splitlines():
            if line.startswith("data:"):
                out.append(json.loads(line[5:].strip()))
        return out[-1] if out else None
    try:
        return resp.json()
    except Exception:
        return resp.text

class MCP:
    def __init__(self):
        self.sid = None
        self.id = 0
        r = self.rpc("initialize", {"protocolVersion": "2025-03-26", "capabilities": {}, "clientInfo": {"name": "cli", "version": "1"}})
        self.notify("notifications/initialized", {})
    def rpc(self, method, params):
        self.id += 1
        h = dict(HDR)
        if self.sid: h["mcp-session-id"] = self.sid
        resp = requests.post(URL, headers=h, json={"jsonrpc":"2.0","id":self.id,"method":method,"params":params}, timeout=120)
        if "mcp-session-id" in resp.headers:
            self.sid = resp.headers["mcp-session-id"]
        return parse(resp)
    def notify(self, method, params):
        h = dict(HDR)
        if self.sid: h["mcp-session-id"] = self.sid
        requests.post(URL, headers=h, json={"jsonrpc":"2.0","method":method,"params":params}, timeout=60)
    def tools(self):
        return self.rpc("tools/list", {})
    def call(self, name, args):
        return self.rpc("tools/call", {"name": name, "arguments": args})

if __name__ == "__main__":
    m = MCP()
    if sys.argv[1] == "list":
        r = m.tools()
        for t in r["result"]["tools"]:
            print("==", t["name"])
            print(t.get("description","")[:600])
            print(json.dumps(t.get("inputSchema",{}))[:1500])
            print()
    else:
        name = sys.argv[1]
        args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
        r = m.call(name, args)
        print(json.dumps(r, indent=1)[:20000])
EOF
