            vals = []
            for c in row:
                if c.value is not None:
                    v = c.value
                    s = f"{c.coordinate}={v!r}"
                    if c.comment:
                        s += f" [COMMENT: {c.comment.text!r}]"
                    vals.append(s)
                elif c.comment:
                    vals.append(f"{c.coordinate}=<None> [COMMENT: {c.comment.text!r}]")
            if vals:
                print(" | ".join(vals))
        # merged cells
        if ws.merged_cells.ranges:
            print("MERGED:", [str(r) for r in ws.merged_cells.ranges])
        # hidden rows/cols
        hr = [r for r, d in ws.row_dimensions.items() if d.hidden]
        hc = [c for c, d in ws.column_dimensions.items() if d.hidden]
        if hr or hc:
            print("HIDDEN rows:", hr, "cols:", hc)
        try:
            if ws.data_validations.dataValidation:
                print("DATA VALIDATIONS:", [(dv.sqref, dv.formula1) for dv in ws.data_validations.dataValidation])
        except Exception:
            pass
    try:
        if wb.defined_names:
            print("DEFINED NAMES:", list(wb.defined_names.keys()) if hasattr(wb.defined_names,'keys') else wb.defined_names)
    except Exception:
        pass
