import sys, docx
from docx.shared import Pt
for path in sys.argv[1:]:
    print("#"*100)
    print("FILE:", path)
    d = docx.Document(path)
    cp = d.core_properties
    print("Core props: author=%r last_modified_by=%r created=%r modified=%r title=%r subject=%r comments=%r" % (cp.author, cp.last_modified_by, cp.created, cp.modified, cp.title, cp.subject, cp.comments))
    for s in d.sections:
        for p in s.header.paragraphs:
            if p.text.strip(): print("[HEADER]", p.text)
        for p in s.footer.paragraphs:
            if p.text.strip(): print("[FOOTER]", p.text)
    body = d.element.body
    from docx.table import Table
    from docx.text.paragraph import Paragraph
    for child in body.iterchildren():
        tag = child.tag.split('}')[1]
        if tag == 'p':
            p = Paragraph(child, d)
            if p.text.strip():
                print(f"[{p.style.name}] {p.text}")
        elif tag == 'tbl':
            t = Table(child, d)
            print("[TABLE]")
            for r in t.rows:
                print("   | " + " | ".join(c.text.replace('\n',' / ') for c in r.cells))
    # comments
    try:
        part = d.part
        for rel in part.rels.values():
            if 'comments' in rel.reltype:
                print("[HAS COMMENTS PART]", rel.target_ref)
                import re
                xml = rel.target_part.blob.decode('utf8', 'replace')
                print(re.sub('<[^>]+>', ' ', xml)[:3000])
    except Exception as e:
        print("comments err", e)
