import sys, os, re, subprocess, openpyxl, docx, email
pat = re.compile(sys.argv[1], re.I)
for root, dirs, files in os.walk('/filesystem'):
    for f in files:
        p = os.path.join(root, f)
        txt = ''
        try:
            if f.endswith('.pdf'):
                txt = subprocess.run(['pdftotext','-layout',p,'-'],capture_output=True,text=True).stdout
            elif f.endswith('.xlsx'):
                wb = openpyxl.load_workbook(p, data_only=True)
                lines=[]
                for ws in wb.worksheets:
                    for row in ws.iter_rows(values_only=True):
                        if any(v is not None for v in row):
                            lines.append(ws.title+': '+' | '.join('' if v is None else str(v) for v in row))
                txt='\n'.join(lines)
            elif f.endswith('.docx'):
                d = docx.Document(p)
                lines=[pp.text for pp in d.paragraphs]
                for t in d.tables:
                    for r in t.rows:
                        lines.append(' | '.join(c.text for c in r.cells))
                txt='\n'.join(lines)
            elif f.endswith('.eml'):
                txt=open(p,errors='replace').read()
        except Exception as e:
            txt=''
        for line in txt.splitlines():
            if pat.search(line):
                print(f"{p}: {line.strip()[:400]}")
